import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

import { convertPhonemes } from "./convert";
import type { LexiconEntry } from "./dictionary";
import { resolveFactPath, type ReviewMap } from "../records/reviews";

/**
 * Data integrity for the curated pronunciation lexicon. Most of it is generated by
 * scripts/build-name-lexicon.mjs from the Book of Mormon Pronunciation Guide, so a bad parse
 * would otherwise land 340 wrong pronunciations at once and nothing would notice.
 */
const DATA_DIR = path.resolve(__dirname, "../../data");
const readData = (file: string) => JSON.parse(readFileSync(path.join(DATA_DIR, file), "utf8"));

const lexicon: LexiconEntry[] = readData("deseret-lexicon.json");
const reviews: ReviewMap = readData("deseret-lexicon.reviews.json");

/** The 39 ARPAbet phonemes, with an optional CMUdict stress digit on vowels. */
const PHONEME =
  /^(AA|AE|AH|AO|AW|AY|EH|ER|EY|IH|IY|OW|OY|UH|UW)[0-2]?$|^(B|CH|D|DH|F|G|HH|JH|K|L|M|N|NG|P|R|S|SH|T|TH|V|W|Y|Z|ZH)$/;

describe("curated pronunciation lexicon", () => {
  it("carries the whole guide plus derived plurals, not a partial parse", () => {
    // ~340 guide entries plus ~308 plurals. A dropped symbol in the respelling key makes every
    // entry using it fail to parse and silently vanish, so pin a floor rather than non-empty.
    expect(lexicon.length).toBeGreaterThanOrEqual(600);
  });

  it("has the plurals the corpus leans on", () => {
    const ids = new Set(lexicon.map((entry) => entry.id));
    // Lamanites (896) and Nephites (623) are the two most frequent words CMUdict misses.
    for (const name of ["lamanites", "nephites", "zoramites", "jaredites"]) {
      expect(ids, `missing ${name}`).toContain(name);
    }
  });

  it("has unique, lowercase ids", () => {
    const ids = lexicon.map((entry) => entry.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ids) {
      expect(id, `${id} is not lowercase`).toBe(id.toLowerCase());
      expect(id, `${id} has an unexpected shape`).toMatch(/^[a-z][a-z'–-]*$/);
    }
  });

  it("uses only real ARPAbet phonemes", () => {
    for (const entry of lexicon) {
      expect(entry.phonemes.length, `${entry.id} has no phonemes`).toBeGreaterThan(0);
      for (const phoneme of entry.phonemes) {
        expect(phoneme, `${entry.id} has phoneme "${phoneme}"`).toMatch(PHONEME);
      }
    }
  });

  it("cites an https source for every entry", () => {
    for (const entry of lexicon) {
      expect(entry.sources.length, `${entry.id} has no source`).toBeGreaterThan(0);
      for (const source of entry.sources) {
        expect(source, `${entry.id} source`).toMatch(/^https:\/\//);
      }
    }
  });

  it("converts every entry to Deseret", () => {
    for (const entry of lexicon) {
      expect(convertPhonemes(entry.phonemes), `${entry.id} produced nothing`).toMatch(
        /^[\u{10428}-\u{1044F}]+$/u,
      );
    }
  });

  it("carries the names the corpus actually needs", () => {
    const ids = new Set(lexicon.map((entry) => entry.id));
    for (const name of ["nephi", "lamanite", "zarahemla", "moroni", "coriantumr"]) {
      expect(ids, `missing ${name}`).toContain(name);
    }
  });

  it("has no review pointing at a fact that does not exist", () => {
    for (const factPath of Object.keys(reviews)) {
      expect(resolveFactPath(lexicon, factPath), `dangling review: ${factPath}`).toBeDefined();
    }
  });
});
